arguments.command:
cd /home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill && for b in rachel monica phoebe joey chandler ross; do
  git log origin/friend/$b --format='COMMIT %H%nDATE %ci%n%B---END---' --reverse | awk -v br="friend/$b" '
    /^COMMIT /{sha=$2}
    /^DATE /{date=$2" "$3}
    /^Episode: S05\/E25/{ep=1}
    /^---END---/{
      if (ep) { print "BRANCH="br; print "SHA="sha; print "DATE="date; }
      ep=0
    }
  ' 
done | head -80
